/* ─── Radius pro SVG mapu podle módu a km ─── */
function getModeRadius(mode: string, km: number): number {
  if (mode === "anywhere") return 999;
  if (mode === "kraj") return 80;
  if (mode === "okres") return 40;
  if (mode === "km") return Math.round(km * 0.95); // px ≈ km ve viewBox
  return 20; // city
}

/* ─── Mapování souřadnic → SVG 500×280 ─── */
// ČR bounding box: lng 12.09–18.87, lat 48.55–51.06
function latLngToSVG(lat: number, lng: number) {
  // Simplemaps CZ map: viewBox 0 0 1000 570
  // Bounding box approx: lng 12.09–18.87, lat 48.55–51.06
  const x = ((lng - 12.09) / (18.87 - 12.09)) * 970 + 15;
  const y = ((51.06 - lat) / (51.06 - 48.55)) * 540 + 15;
  return { x, y };
}

