export default function ZacitPage() {
  const router = useRouter();
  const { signUp, signIn } = useAuth();
  const { senior, setSenior } = useA11y();
  const [step, setStep] = useState(1);
  const [seniorBanner, setSeniorBanner] = useState(false);
  const [a, setA] = useState<Answers>({
    forWhom: null, careType: null, location: "", locationData: null,
    distanceMode: "city", distanceKm: 20,
    urgency: null, urgencyNote: "", conditions: [],
  });
  const set = (patch: Partial<Answers>) => setA((p) => ({ ...p, ...patch }));

  const next = () => setStep((s) => Math.min(s + 1, TOTAL + 1));
  const back = () => setStep((s) => Math.max(s - 1, 1));

  const subject = SUBJECT[a.forWhom ?? ""] ?? "vašeho blízkého";

  /** Volba „Pro sebe" / „Pro partnera" = vyplňuje pravděpodobně sám senior.
      Zapneme větší písmo automaticky — s viditelnou možností vrátit zpět. */
  function pickForWhom(v: string) {
    set({ forWhom: v });
    if ((v === "self" || v === "partner") && !senior) {
      setSenior(true);
      setSeniorBanner(true);
    }
    setTimeout(next, 180);
  }

  async function continueGuest() {
    await signIn("host@seniorhouse.cz", "demo");
    router.push("/pece");
  }
  async function continueWith(provider: string) {
    await signUp("host@seniorhouse.cz", "demo", "Rodina", "family");
    router.push("/pece");
  }

  return (
    <main className="flex min-h-screen flex-col bg-paper">
      <header className="flex items-center justify-between px-5 py-4 sm:px-8">
        <Logo />
        <div className="flex items-center gap-4">
          <a
            href={PHONE_TEL}
            className="flex items-center gap-2 text-[0.9333rem] font-medium text-sage-d hover:text-sage a11y-tap"
          >
            <Phone size={16} />
            <span className="hidden sm:inline">Raději po telefonu?</span> {PHONE_DISPLAY}
          </a>
          <Link href="/" className="text-[0.8667rem] text-ink-3 hover:text-ink a11y-tap">Zavřít</Link>
        </div>
      </header>

      {/* Oznámení: automaticky zapnuté větší písmo */}
      {seniorBanner && senior && (
        <div className="mx-auto w-full max-w-xl px-5 pb-2" role="status" aria-live="polite">
          <div className="flex items-center gap-3 rounded-xl border border-sage-bd bg-sage-l px-4 py-3">
            <Eye size={18} className="shrink-0 text-sage-d" />
            <p className="flex-1 text-[0.9333rem] leading-snug text-sage-d">
              Zapnuli jsme <strong>větší písmo</strong> pro pohodlnější čtení.
            </p>
            <button
              onClick={() => { setSenior(false); setSeniorBanner(false); }}
              className="shrink-0 rounded-lg border border-sage-bd bg-surface px-3 py-1.5 text-[0.8667rem] font-medium text-ink-2 hover:text-ink a11y-tap"
            >
              Vrátit menší
            </button>
            <button
              onClick={() => setSeniorBanner(false)}
              aria-label="Zavřít oznámení"
              className="shrink-0 text-sage-d/60 hover:text-sage-d a11y-tap"
            >
              <X size={16} />
            </button>
          </div>
        </div>
      )}

      {step <= TOTAL && (
        <div className="mx-auto w-full max-w-xl px-5">
          <div className="flex items-center justify-between text-[0.8rem] text-ink-3">
            <span>Krok {step} z {TOTAL}</span>
            <span>{Math.round((step / TOTAL) * 100)} %</span>
          </div>
          <div className="mt-1.5 h-1.5 w-full overflow-hidden rounded-full bg-surface-2">
            <div
              className="h-full rounded-full bg-sage transition-all duration-500"
              style={{ width: `${(step / TOTAL) * 100}%` }}
            />
          </div>
        </div>
      )}

      <div className="flex flex-1 items-center justify-center px-5 py-8">
        <div className="w-full max-w-xl">
          {step === 1 && (
            <Step title="Pro koho hledáte péči?" subtitle="Pomůže nám to mluvit s vámi lidsky — ne formuláři.">
              <Choices
                options={[
                  { v: "mom", label: "Pro maminku", icon: Heart },
                  { v: "dad", label: "Pro tatínka", icon: Heart },
                  { v: "partner", label: "Pro partnera", icon: HandHeart },
                  { v: "other", label: "Pro jiného blízkého", icon: Users },
                  { v: "self", label: "Pro sebe", icon: UserRound },
                ]}
                value={a.forWhom}
                onPick={pickForWhom}
              />
            </Step>
          )}

          {step === 2 && (
            <Step title="Jaký druh pomoci hledáte?" subtitle="Pokud si nejste jistí, nevadí — projdeme to společně.">
              <Choices
                columns
                options={[
                  { v: "senior_home", label: "Domov pro seniory", icon: Building2 },
                  { v: "special", label: "Domov se zvláštním režimem", icon: Brain },
                  { v: "home", label: "Domácí péče", icon: Home },
                  { v: "respite", label: "Odlehčovací pobyt", icon: Sun },
                  { v: "daycare", label: "Denní stacionář", icon: Activity },
                  { v: "unsure", label: "Nejsem si jistý", icon: HelpCircle },
                ]}
                value={a.careType}
                onPick={(v) => { set({ careType: v }); setTimeout(next, 180); }}
              />
            </Step>
          )}

          {step === 3 && (
            <LocationStep a={a} set={set} onBack={back} onNext={next} />
          )}

          {step === 4 && (
            <Step title="Jak naléhavá je situace?" subtitle="Podle toho seřadíme zařízení i další kroky. Nikam vás netlačíme.">
              <UrgencyStep a={a} set={set} onBack={back} onNext={next} />
            </Step>
          )}

          {step === 5 && (
            <Step title="Jaké obtíže řešíte?" subtitle="Vyberte vše, co odpovídá. Pomůže nám to najít zařízení se správnou zkušeností.">
              <MultiChoices
                options={[
                  { v: "alzheimer", label: "Alzheimerova choroba" },
                  { v: "dementia", label: "Demence" },
                  { v: "mobility", label: "Omezená mobilita" },
                  { v: "stroke", label: "Po cévní mozkové příhodě" },
                  { v: "fulltime", label: "Potřeba celodenní péče" },
                  { v: "loneliness", label: "Osamělost" },
                  { v: "other", label: "Jiná situace" },
                ]}
                value={a.conditions}
                onToggle={(v) =>
                  set({
                    conditions: a.conditions.includes(v)
                      ? a.conditions.filter((x) => x !== v)
                      : [...a.conditions, v],
                  })
                }
              />
              <NavRow onBack={back} onNext={next} nextLabel="Zobrazit doporučení" />
            </Step>
          )}

          {step === 6 && (
            <Recommendation a={a} subject={subject} onBack={back} onNext={next} />
          )}

          {step === TOTAL + 1 && (
            <SaveProgress subject={subject} answers={a} onGuest={continueGuest} onProvider={continueWith} />
          )}
        </div>
      </div>
    </main>
  );
}

const SUBJECT: Record<string, string> = {
  mom: "maminky", dad: "tatínka", partner: "partnera",
  other: "vašeho blízkého", self: "vás",
};

/* ─────────────────────────────────────
   Krok 3: Lokalita s mapou a autocomplete
   ───────────────────────────────────── */
function LocationStep({ a, set, onBack, onNext }: {
  a: Answers; set: (p: Partial<Answers>) => void; onBack: () => void; onNext: () => void;
}) {
  const [query, setQuery] = useState(a.location);
  const [suggestions, setSuggestions] = useState<typeof CITIES>([]);
  const [open, setOpen] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const svgPoint = a.locationData ? latLngToSVG(a.locationData.lat, a.locationData.lng) : null;
  const radius = getModeRadius(a.distanceMode, a.distanceKm);

  function normalize(s: string) {
    return s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  }

  function handleInput(val: string) {
    setQuery(val);
    set({ location: val, locationData: null });
    if (val.length >= 2) {
      const q = normalize(val);
      const hits = CITIES.filter((c) => {
        const cn = normalize(c.city);
        return cn.startsWith(q) || cn.includes(q);
      }).slice(0, 7);
      setSuggestions(hits);
      setOpen(hits.length > 0);
    } else {
      setSuggestions([]);
      setOpen(false);
    }
  }

  function selectCity(c: typeof CITIES[0]) {
    setQuery(c.city);
    set({ location: c.city, locationData: { lat: c.lat, lng: c.lng, city: c.city, region: c.region } });
    setSuggestions([]);
    setOpen(false);
  }

  const DISTANCE_MODES: { v: Answers["distanceMode"]; label: string }[] = [
    { v: "city", label: "Město" },
    { v: "okres", label: "Okres" },
    { v: "kraj", label: "Kraj" },
    { v: "km", label: "KM" },
    { v: "anywhere", label: "Nezáleží" },
  ];

  const modeLabel = a.distanceMode === "km"
    ? `${a.distanceKm} km`
    : a.distanceMode === "anywhere"
    ? "Celá ČR"
    : a.distanceMode === "city"
    ? "V obci"
    : a.distanceMode === "okres"
    ? "V okresu"
    : "V kraji";

  return (
    <div className="animate-in">
      <h1 className="font-serif text-[1.8rem] font-medium leading-tight text-ink sm:text-[2rem]">
        Kde péči hledáte?
      </h1>
      <p className="mt-2 text-[1rem] leading-relaxed text-ink-2 a11y-dim">
        Zadejte město — ukážeme vám péči v dosahu.
      </p>

      <div className="mt-6 space-y-4">
        {/* Autocomplete */}
        <div>
          <label className="field-label flex items-center gap-1.5">
            <MapPin size={14} className="text-sage" /> Město nebo obec
          </label>
          <div className="relative">
            <input
              ref={inputRef}
              autoFocus
              className="field-input text-[1rem]"
              placeholder="např. Praha, Liberec, Brno…"
              value={query}
              onChange={(e) => handleInput(e.target.value)}
              onFocus={() => suggestions.length > 0 && setOpen(true)}
              onBlur={() => setTimeout(() => setOpen(false), 150)}
            />
            {open && (
              <div className="absolute left-0 right-0 top-full z-30 mt-1 overflow-hidden rounded-xl border border-line bg-surface shadow-soft-lg">
                {suggestions.map((c) => (
                  <button
                    key={c.city + c.region}
                    onMouseDown={(e) => { e.preventDefault(); selectCity(c); }}
                    className="flex w-full items-center justify-between px-4 py-2.5 text-left text-[0.9333rem] hover:bg-surface-2"
                  >
                    <span className="font-medium text-ink">{c.city}</span>
                    <span className="text-[0.8rem] text-ink-3">{c.region} kraj</span>
                  </button>
                ))}
              </div>
            )}
          </div>
          {a.locationData && (
            <p className="mt-1.5 flex items-center gap-1.5 text-[0.8rem] text-sage-d">
              <Check size={13} strokeWidth={2.5} /> {a.locationData.city} · {a.locationData.region} kraj
            </p>
          )}
        </div>

        {/* Oblast hledání — Město / Okres / Kraj / KM / Nezáleží */}
        <div>
          <label className="field-label">Oblast hledání</label>
          <div className="grid grid-cols-3 gap-1.5 sm:grid-cols-5">
            {DISTANCE_MODES.map((m) => (
              <button
                key={m.v}
                onClick={() => set({ distanceMode: m.v })}
                className={`rounded-xl border py-2.5 text-[0.8333rem] font-medium transition-colors a11y-tap ${
                  a.distanceMode === m.v
                    ? "border-sage bg-sage-l text-sage-d"
                    : "border-line bg-surface text-ink-2 hover:border-line-2"
                }`}
              >
                {m.label}
              </button>
            ))}
          </div>

          {/* Slider pro KM */}
          {a.distanceMode === "km" && (
            <div className="mt-3 rounded-xl border border-line bg-surface px-4 py-3">
              <div className="mb-2 flex items-center justify-between text-[0.8rem]">
                <span className="text-ink-2">Okruh</span>
                <span className="font-semibold text-sage-d">{a.distanceKm} km</span>
              </div>
              <input
                type="range"
                min={5}
                max={150}
                step={5}
                value={a.distanceKm}
                onChange={(e) => set({ distanceKm: Number(e.target.value) })}
                className="w-full accent-sage"
              />
              <div className="mt-1 flex justify-between text-[0.6667rem] text-ink-3">
                <span>5 km</span><span>150 km</span>
              </div>
            </div>
          )}
        </div>

        {/* Mapa ČR */}
        <div className="overflow-hidden rounded-xl border border-line bg-surface">
          <div className="border-b border-line px-3 py-2">
            <span className="text-[0.7333rem] font-semibold uppercase tracking-wider text-ink-3">
              {a.locationData
                ? `${a.locationData.city} · ${modeLabel}`
                : "Mapa ČR — vyberte město výše"}
            </span>
          </div>
          <div className="px-3 py-2">
            <CzechMapSVG
              point={svgPoint}
              radius={radius}
              everywhere={a.distanceMode === "anywhere"}
              mode={a.distanceMode}
              activeKraj={a.locationData ? regionToKrajPath(a.locationData.region) : null}
            />
          </div>
        </div>
      </div>

      <NavRow onBack={onBack} onNext={onNext} nextDisabled={!query.trim()} />
    </div>
  );
}

/* Mapuje region z dat měst na název kraje v KRAJ_PATHS. */
function regionToKrajPath(region: string): string {
  if (region === "Praha") return "Praha";
  if (region === "Kraj Vysočina") return "Kraj Vysočina";
  return `${region} kraj`;
}

/* ─── SVG mapa ČR s kraji ─── */
function CzechMapSVG({ point, radius, everywhere, mode, activeKraj }: {
  point: { x: number; y: number } | null;
  radius: number;
  everywhere: boolean;
  mode?: string;
  activeKraj?: string | null;
}) {
  const krajMode = mode === "kraj" && !!activeKraj;
  return (
    <svg
      viewBox="0 0 1000 570"
      xmlns="http://www.w3.org/2000/svg"
      className="w-full"
      style={{ maxHeight: 160 }}
    >
      {/* Kraje — Simplemaps reálné paths */}
      {KRAJ_PATHS.map((k) => {
        const isActive = krajMode && k.name === activeKraj;
        return (
          <path
            key={k.name}
            d={k.d}
            fill={
              isActive
                ? "#4A7C5A"
                : everywhere && point
                ? "#4A7C5A18"
                : "#f2efea"
            }
            fillOpacity={isActive ? 0.85 : 1}
            stroke={isActive ? "#33603F" : "#ccc8c0"}
            strokeWidth={isActive ? "1.8" : "1.2"}
            strokeLinejoin="round"
          />
        );
      })}

      {/* Okruh kolem bodu — jen v režimech s poloměrem (ne „kraj") */}
      {point && !everywhere && !krajMode && (
        <circle
          cx={point.x} cy={point.y} r={radius}
          fill="#4A7C5A" fillOpacity="0.13"
          stroke="#4A7C5A" strokeWidth="2" strokeDasharray="6 4"
        />
      )}

      {/* Bod — vybrané město (v režimu kraj skryjeme, kraj mluví sám za sebe) */}
      {point && !krajMode && (
        <>
          <circle cx={point.x} cy={point.y} r={12} fill="#4A7C5A" fillOpacity="0.25" />
          <circle cx={point.x} cy={point.y} r={6} fill="#4A7C5A" />
        </>
      )}

      {/* Placeholder text */}
      {!point && (
        <text x="500" y="290" textAnchor="middle" fill="#bbb4ac" fontSize="20">
          Zadejte město výše
        </text>
      )}
    </svg>
  );
}

/* ─────────────────────────────────────
   Krok 4: Naléhavost s poznámkovým polem pro "Jiné"
   ───────────────────────────────────── */
function UrgencyStep({ a, set, onBack, onNext }: {
  a: Answers; set: (p: Partial<Answers>) => void; onBack: () => void; onNext: () => void;
}) {
  const isDo = ["1m", "3m", "6m", "1y"].includes(a.urgency ?? "");

  return (
    <div className="space-y-3">
      {/* IHNED */}
      <button
        onClick={() => set({ urgency: "now" })}
        className={`flex w-full items-center gap-3 rounded-2xl border px-4 py-3.5 text-left transition-all a11y-tap ${
          a.urgency === "now" ? "border-sage bg-sage-l shadow-soft" : "border-line bg-surface hover:border-sage-bd"
        }`}
      >
        <span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${a.urgency === "now" ? "bg-sage text-white" : "bg-surface-2 text-ink-2"}`}>
          <Zap size={18} strokeWidth={2} />
        </span>
        <span className="flex-1">
          <span className="block text-[1rem] font-semibold text-ink">IHNED</span>
          <span className="block text-[0.8rem] text-ink-3">Řešíme to v řádu dní</span>
        </span>
        <span className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 ${a.urgency === "now" ? "border-sage bg-sage text-white" : "border-line-2"}`}>
          {a.urgency === "now" && <Check size={11} strokeWidth={3} />}
        </span>
      </button>

      {/* DO — jako karta, uvnitř 4 pill-tlačítka */}
      <div
        className={`rounded-2xl border px-4 py-3.5 transition-all ${
          isDo ? "border-sage bg-sage-l shadow-soft" : "border-line bg-surface"
        }`}
      >
        <div className="flex items-center gap-3">
          <span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${isDo ? "bg-sage text-white" : "bg-surface-2 text-ink-2"}`}>
            <Calendar size={18} strokeWidth={2} />
          </span>
          <span className="flex-1">
            <span className="block text-[1rem] font-semibold text-ink">DO</span>
            <span className="block text-[0.8rem] text-ink-3">Víme přibližně kdy</span>
          </span>
          <span className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 ${isDo ? "border-sage bg-sage text-white" : "border-line-2"}`}>
            {isDo && <Check size={11} strokeWidth={3} />}
          </span>
        </div>
        <div className="mt-3 grid grid-cols-4 gap-2">
          {([
            { v: "1m", label: "1 měs." },
            { v: "3m", label: "3 měs." },
            { v: "6m", label: "6 měs." },
            { v: "1y",  label: "1 roku" },
          ] as const).map((o) => (
            <button
              key={o.v}
              onClick={() => set({ urgency: o.v })}
              className={`rounded-lg border py-2 text-center text-[0.8rem] font-medium transition-colors a11y-tap ${
                a.urgency === o.v
                  ? "border-sage bg-sage text-white"
                  : "border-line bg-surface text-ink-2 hover:border-sage-bd"
              }`}
            >
              {o.label}
            </button>
          ))}
        </div>
      </div>

      {/* NESPĚCHÁ */}
      <button
        onClick={() => set({ urgency: "relaxed" })}
        className={`flex w-full items-center gap-3 rounded-2xl border px-4 py-3.5 text-left transition-all a11y-tap ${
          a.urgency === "relaxed" ? "border-sage bg-sage-l shadow-soft" : "border-line bg-surface hover:border-sage-bd"
        }`}
      >
        <span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${a.urgency === "relaxed" ? "bg-sage text-white" : "bg-surface-2 text-ink-2"}`}>
          <Leaf size={18} strokeWidth={2} />
        </span>
        <span className="flex-1">
          <span className="block text-[1rem] font-semibold text-ink">NESPĚCHÁ</span>
          <span className="block text-[0.8rem] text-ink-3">Plánujeme dopředu v klidu</span>
        </span>
        <span className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 ${a.urgency === "relaxed" ? "border-sage bg-sage text-white" : "border-line-2"}`}>
          {a.urgency === "relaxed" && <Check size={11} strokeWidth={3} />}
        </span>
      </button>

      {/* JINÉ */}
      <div>
        <button
          onClick={() => set({ urgency: "other" })}
          className={`flex w-full items-center gap-3 rounded-2xl border px-4 py-3.5 text-left transition-all a11y-tap ${
            a.urgency === "other" ? "border-sage bg-sage-l shadow-soft" : "border-line bg-surface hover:border-sage-bd"
          }`}
        >
          <span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${a.urgency === "other" ? "bg-sage text-white" : "bg-surface-2 text-ink-2"}`}>
            <MoreHorizontal size={18} strokeWidth={2} />
          </span>
          <span className="flex-1">
            <span className="block text-[1rem] font-semibold text-ink">JINÉ</span>
          </span>
          <span className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 ${a.urgency === "other" ? "border-sage bg-sage text-white" : "border-line-2"}`}>
            {a.urgency === "other" && <Check size={11} strokeWidth={3} />}
          </span>
        </button>
        {a.urgency === "other" && (
          <div className="mt-2">
            <textarea
              autoFocus
              rows={2}
              className="field-input resize-none text-[0.9333rem]"
              placeholder="Popište vaši situaci…"
              value={a.urgencyNote}
              onChange={(e) => set({ urgencyNote: e.target.value })}
            />
          </div>
        )}
      </div>

      <NavRow onBack={onBack} onNext={onNext} nextDisabled={!a.urgency} />
    </div>
  );
}

/* ─────────────────────────────────────
   Sdílené stavební bloky
   ───────────────────────────────────── */
function Step({ title, subtitle, children }: { title: string; subtitle?: string; children: React.ReactNode }) {
  return (
    <div className="animate-in">
      <h1 className="font-serif text-[1.8rem] font-medium leading-tight text-ink sm:text-[2rem]">{title}</h1>
      {subtitle && <p className="mt-2 text-[1rem] leading-relaxed text-ink-2 a11y-dim">{subtitle}</p>}
      <div className="mt-7">{children}</div>
    </div>
  );
}

type Opt = { v: string; label: string; icon?: typeof Heart; note?: string };

function Choices({ options, value, onPick, columns = false }: {
  options: Opt[]; value: string | null; onPick: (v: string) => void; columns?: boolean;
}) {
  return (
    <div className={columns ? "grid gap-2.5 sm:grid-cols-2" : "space-y-2.5"}>
      {options.map((o) => {
        const active = value === o.v;
        const Icon = o.icon;
        return (
          <button
            key={o.v}
            onClick={() => onPick(o.v)}
            className={`flex w-full items-center gap-3.5 rounded-2xl border px-4 py-4 text-left transition-all a11y-tap ${
              active ? "border-sage bg-sage-l shadow-soft" : "border-line bg-surface hover:border-sage-bd"
            }`}
          >
            {Icon && (
              <span className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${
                active ? "bg-sage text-white" : "bg-surface-2 text-ink-2"
              }`}>
                <Icon size={19} />
              </span>
            )}
            <span className="min-w-0 flex-1">
              <span className="block text-[1.0333rem] font-medium text-ink">{o.label}</span>
              {o.note && <span className="block text-[0.8333rem] text-ink-3">{o.note}</span>}
            </span>
            <span className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border-2 ${
              active ? "border-sage bg-sage text-white" : "border-line-2"
            }`}>
              {active && <Check size={13} strokeWidth={3} />}
            </span>
          </button>
        );
      })}
    </div>
  );
}

function MultiChoices({ options, value, onToggle }: {
  options: Opt[]; value: string[]; onToggle: (v: string) => void;
}) {
  return (
    <div className="grid gap-2.5 sm:grid-cols-2">
      {options.map((o) => {
        const active = value.includes(o.v);
        return (
          <button
            key={o.v}
            onClick={() => onToggle(o.v)}
            className={`flex items-center gap-3 rounded-2xl border px-4 py-3.5 text-left transition-all a11y-tap ${
              active ? "border-sage bg-sage-l" : "border-line bg-surface hover:border-sage-bd"
            }`}
          >
            <span className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-md border-2 ${
              active ? "border-sage bg-sage text-white" : "border-line-2"
            }`}>
              {active && <Check size={13} strokeWidth={3} />}
            </span>
            <span className="text-[1rem] font-medium text-ink">{o.label}</span>
          </button>
        );
      })}
    </div>
  );
}

function NavRow({ onBack, onNext, nextLabel = "Pokračovat", nextDisabled = false }: {
  onBack: () => void; onNext: () => void; nextLabel?: string; nextDisabled?: boolean;
}) {
  return (
    <div className="mt-7 flex items-center justify-between">
      <button onClick={onBack} className="flex items-center gap-1.5 text-[0.9333rem] text-ink-2 hover:text-ink a11y-tap">
        <ArrowLeft size={16} /> Zpět
      </button>
      <button onClick={onNext} disabled={nextDisabled} className="btn btn-primary text-[0.9333rem]">
        {nextLabel} <ArrowRight size={16} />
      </button>
    </div>
  );
}

/* ─── Krok 6: Doporučení ─── */
function Recommendation({ a, subject, onBack, onNext }: {
  a: Answers; subject: string; onBack: () => void; onNext: () => void;
}) {
  const rec = buildRecommendation(a);
  return (
    <div className="animate-in">
      <div className="mb-1 flex items-center gap-2 text-[0.8rem] font-semibold uppercase tracking-wider text-sage-d">
        <Sparkles size={14} /> Vaše doporučení
      </div>
      <h1 className="font-serif text-[1.6rem] font-medium leading-tight text-ink sm:text-[1.8rem]">
        Připravili jsme první kroky pro péči o {subject}.
      </h1>
      <p className="mt-1.5 text-[0.8667rem] leading-relaxed text-ink-2 a11y-dim">{rec.intro}</p>

      <div className="mt-4 card p-4">
        <div className="card-lbl mb-2">Vhodné typy služeb</div>
        <div className="flex flex-wrap gap-1.5">
          {rec.services.map((s) => (
            <span key={s} className="chip border-sage-bd bg-sage-l text-sage-d">{s}</span>
          ))}
        </div>
      </div>

      <div className="mt-3 card p-4">
        <div className="card-lbl mb-2">Doporučený postup</div>
        <ol className="space-y-2">
          {rec.steps.map((s, i) => (
            <li key={i} className="flex gap-2.5">
              <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-sage-l text-[0.7333rem] font-semibold text-sage-d mt-0.5">{i + 1}</span>
              <span className="text-[0.8667rem] leading-snug text-ink-2 a11y-dim">{s}</span>
            </li>
          ))}
        </ol>
      </div>

      <div className="mt-3 rounded-xl bg-sage-l px-3.5 py-3 text-[0.8333rem] leading-relaxed text-sage-d">
        <ShieldCheck size={14} className="mb-0.5 inline" /> Bezplatně vám přidělíme koordinátorku péče, která vše vyřídí s vámi.
      </div>

      <div className="mt-5 flex items-center justify-between">
        <button onClick={onBack} className="flex items-center gap-1.5 text-[0.9333rem] text-ink-2 hover:text-ink a11y-tap">
          <ArrowLeft size={16} /> Zpět
        </button>
        <button onClick={onNext} className="btn btn-primary text-[0.9333rem]">
          Pokračovat do systému <ArrowRight size={16} />
        </button>
      </div>
    </div>
  );
}

function buildRecommendation(a: Answers) {
  const hasMemory = a.conditions.some((c) => ["alzheimer", "dementia"].includes(c));
  const fulltime = a.conditions.includes("fulltime") || a.conditions.includes("stroke");
  const urgent = a.urgency === "now" || a.urgency === "month";

  const services: string[] = [];
  if (hasMemory) services.push("Domov se zvláštním režimem");
  if (fulltime && !hasMemory) services.push("Domov pro seniory");
  if (!fulltime && !hasMemory) services.push("Domácí péče", "Denní stacionář");
  if (urgent) services.push("Odlehčovací pobyt");
  if (services.length === 0) services.push("Domov pro seniory", "Domácí péče");

  const intro = hasMemory
    ? "Podle vašich odpovědí potřebujete zařízení se zkušeností s péčí o paměťové obtíže. Vybrali jsme nejvhodnější směr a první kroky."
    : "Podle vašich odpovědí jsme připravili nejvhodnější typy péče a jasný postup, jak začít — bez zbytečné administrativy.";

  const steps = [
    urgent
      ? "Společně s koordinátorkou oslovíme vhodná zařízení s aktuální volnou kapacitou."
      : "Koordinátorka projde vhodná zařízení ve vašem okolí a doporučí ta nejvhodnější.",
    "Připravíme potřebné dokumenty — žádost, lékařské zprávy, příspěvek na péči.",
    "Podáme žádosti najednou a vy budete mít vše přehledně na jednom místě.",
  ];

  return { intro, services: Array.from(new Set(services)), steps };
}

/* ─────────────────────────────────────
   Poslední krok: uložení postupu s přehledem odpovědí
   ───────────────────────────────────── */
const URGENCY_LABELS: Record<string, string> = {
  now: "Ihned", month: "Do 1 měsíce", "6months": "Do 6 měsíců",
  relaxed: "Nespěchá", other: "Jiné",
};
const CARE_LABELS: Record<string, string> = {
  senior_home: "Domov pro seniory", special: "Domov se zvláštním režimem",
  home: "Domácí péče", respite: "Odlehčovací pobyt", daycare: "Denní stacionář",
  unsure: "Zatím nevím",
};
const FOR_WHOM_LABELS: Record<string, string> = {
  mom: "Maminka", dad: "Tatínek", partner: "Partner", other: "Jiný blízký", self: "Pro sebe",
};

const CONDITIONS_LABELS: Record<string, string> = {
  alzheimer: "Alzheimerova choroba",
  dementia: "Demence",
  mobility: "Omezená mobilita",
  stroke: "Po cévní mozkové příhodě",
  fulltime: "Celodenní péče",
  loneliness: "Osamělost",
  other: "Jiná situace",
};

function SaveProgress({ subject, answers: a, onGuest, onProvider }: {
  subject: string; answers: Answers; onGuest: () => void; onProvider: (p: string) => void;
}) {
  const [mode, setMode] = useState<"choose" | "register">("choose");
  const [infoOpen, setInfoOpen] = useState<string | null>(null);
  const [summaryOpen, setSummaryOpen] = useState(true);

  function goRegister() {
    setSummaryOpen(false); // po volbě uložení tabulku sbalíme, ať se vejde výběr přihlášení
    setMode("register");
  }

  const conditionsText = a.conditions.length > 0
    ? a.conditions.map((c) => CONDITIONS_LABELS[c] ?? c).join(", ")
    : null;

  const summaryItems = [
    a.forWhom ? { label: "Pro koho", value: FOR_WHOM_LABELS[a.forWhom] ?? a.forWhom } : null,
    a.careType ? { label: "Typ péče", value: CARE_LABELS[a.careType] ?? a.careType } : null,
    a.location ? { label: "Lokalita", value: a.locationData ? `${a.locationData.city} · ${a.locationData.region} kraj` : a.location } : null,
    a.distanceMode !== "anywhere"
      ? { label: "Vzdálenost", value: a.distanceMode === "km" ? `${a.distanceKm} km` : a.distanceMode === "city" ? "V obci" : a.distanceMode === "okres" ? "V okresu" : "V kraji" }
      : { label: "Vzdálenost", value: "Celá ČR" },
    a.urgency ? { label: "Naléhavost", value: a.urgency === "other" && a.urgencyNote ? a.urgencyNote : URGENCY_LABELS[a.urgency] ?? a.urgency } : null,
    conditionsText ? { label: "Zdravotní obtíže", value: conditionsText } : null,
  ].filter(Boolean) as { label: string; value: string }[];

  return (
    <div className="animate-in">
      <span className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-sage-l text-sage-d">
        <Check size={28} strokeWidth={2.5} />
      </span>
      <h1 className="mt-5 font-serif text-[1.8rem] font-medium leading-tight text-ink sm:text-[2rem]">
        Chcete si uložit svůj postup?
      </h1>
      <p className="mt-2 text-[1rem] leading-relaxed text-ink-2 a11y-dim">
        Uložíme vaše odpovědi a doporučení, ať se k nim můžete kdykoliv vrátit.
      </p>

      {/* Přehled zadaných odpovědí — sbalitelný */}
      <div className="mt-5 overflow-hidden rounded-2xl border border-line bg-surface text-left">
        <button
          onClick={() => setSummaryOpen((o) => !o)}
          aria-expanded={summaryOpen}
          className="flex w-full items-center gap-2 border-b border-line bg-surface-2 px-4 py-2.5 text-left a11y-tap"
        >
          <span className="flex-1 text-[0.7333rem] font-semibold uppercase tracking-wider text-ink-3">
            Co si uložíme {!summaryOpen && <span className="normal-case font-normal">· {summaryItems.length} údajů</span>}
          </span>
          <ChevronDown
            size={16}
            className={`shrink-0 text-ink-3 transition-transform ${summaryOpen ? "rotate-180" : ""}`}
          />
        </button>
        {summaryOpen && (
          <>
            <div>
              {summaryItems.map((item, i) => (
                <div
                  key={item.label}
                  className={`flex items-start gap-3 px-4 py-2.5 ${i % 2 === 0 ? "bg-surface" : "bg-paper"} ${i < summaryItems.length - 1 ? "border-b border-line" : ""}`}
                >
                  <span className="w-28 shrink-0 text-[0.8rem] text-ink-3 pt-0.5">{item.label}</span>
                  <span className="flex-1 text-[0.8667rem] font-medium text-ink leading-snug">{item.value}</span>
                </div>
              ))}
            </div>
            <div className="flex items-center gap-2 border-t border-sage-bd bg-sage-l/50 px-4 py-2.5">
              <Check size={13} className="shrink-0 text-sage" strokeWidth={2.5} />
              <span className="text-[0.8rem] text-sage-d">Váš profil a doporučení budou připraveny</span>
            </div>
          </>
        )}
      </div>

      {mode === "choose" ? (
        <div className="mt-5 space-y-3 text-left">
          <button
            onClick={goRegister}
            className="flex w-full items-center gap-3.5 rounded-2xl border border-sage bg-sage-l px-4 py-4 text-left transition-all hover:shadow-soft a11y-tap"
          >
            <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-sage text-white">
              <ShieldCheck size={19} />
            </span>
            <span className="flex-1">
              <span className="block text-[1.0333rem] font-medium text-ink">Uložit a pokračovat</span>
              <span className="block text-[0.8333rem] text-ink-2">Vytvořte si účet — doporučení i koordinátorka zůstanou s vámi</span>
            </span>
            <ArrowRight size={18} className="text-sage-d" />
          </button>

          <button
            onClick={onGuest}
            className="flex w-full items-center gap-3.5 rounded-2xl border border-line bg-surface px-4 py-4 text-left transition-all hover:border-line-2 a11y-tap"
          >
            <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-surface-2 text-ink-2">
              <UserRound size={19} />
            </span>
            <span className="flex-1">
              <span className="block text-[1.0333rem] font-medium text-ink">Pokračovat bez účtu</span>
              <span className="block text-[0.8333rem] text-ink-2">Prohlédněte si systém, účet si můžete založit kdykoliv později</span>
            </span>
            <ArrowRight size={18} className="text-ink-3" />
          </button>
        </div>
      ) : (
        <div className="mt-5 space-y-2.5 text-left">
          {/* Oddělení: ověřené přihlášení vs. tabulka shrnutí výše */}
          <div className="flex items-center gap-2 pt-1 text-[0.7333rem] font-semibold uppercase tracking-wider text-ink-3">
            <Lock size={13} /> Ověřené přihlášení
          </div>
          <p className="text-[0.8333rem] text-ink-2 a11y-dim">
            Bezpečné přihlášení, které potvrdí vaši totožnost. Nemusíte si pamatovat heslo.
          </p>

          {/* Bankovní identita */}
          <div className="overflow-hidden rounded-2xl border border-sage-bd bg-sage-l/50">
            <div className="flex items-center gap-3 px-4 py-3.5">
              <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-surface text-sage-d">
                <Landmark size={19} />
              </span>
              <button onClick={() => onProvider("bank_id")} className="min-w-0 flex-1 text-left">
                <span className="block text-[0.9667rem] font-medium text-ink">Bankovní identita</span>
                <span className="block text-[0.8rem] text-ink-2">Přihlášení jako do internetového bankovnictví</span>
              </button>
              <button
                onClick={() => setInfoOpen(infoOpen === "bank_id" ? null : "bank_id")}
                aria-label="Co se stane při přihlášení přes Bankovní identitu"
                aria-expanded={infoOpen === "bank_id"}
                className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-sage-bd bg-surface text-sage-d hover:bg-sage-l"
              >
                <Info size={17} />
              </button>
            </div>
            {infoOpen === "bank_id" && (
              <div className="border-t border-sage-bd/60 bg-surface/70 px-4 py-3 text-[0.8333rem] leading-relaxed text-ink-2">
                Přihlásíte se přes svou banku — stejně jako do internetového bankovnictví.
                Banka nám pouze potvrdí vaše jméno. <span className="font-medium text-ink">Nevidíme
                vaše hesla ani zůstatky a nemáme přístup k vašemu účtu.</span> Slouží jen k ověření,
                že jste to opravdu vy.
              </div>
            )}
          </div>

          {/* Identita občana */}
          <div className="overflow-hidden rounded-2xl border border-line bg-surface">
            <div className="flex items-center gap-3 px-4 py-3.5">
              <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-surface-2 text-sage-d">
                <ShieldCheck size={19} />
              </span>
              <button onClick={() => onProvider("identita_obcana")} className="min-w-0 flex-1 text-left">
                <span className="block text-[0.9667rem] font-medium text-ink">Identita občana</span>
                <span className="block text-[0.8rem] text-ink-2">Mobilní klíč, NIA ID nebo eObčanka</span>
              </button>
              <button
                onClick={() => setInfoOpen(infoOpen === "identita_obcana" ? null : "identita_obcana")}
                aria-label="Co se stane při přihlášení přes Identitu občana"
                aria-expanded={infoOpen === "identita_obcana"}
                className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-line bg-surface text-sage-d hover:border-sage-bd"
              >
                <Info size={17} />
              </button>
            </div>
            {infoOpen === "identita_obcana" && (
              <div className="border-t border-line bg-paper/60 px-4 py-3 text-[0.8333rem] leading-relaxed text-ink-2">
                Přihlášení přes oficiální státní systém (Identita občana / NIA).
                Potvrdí vaši totožnost přes Mobilní klíč, NIA ID nebo eObčanku.
                <span className="font-medium text-ink"> Stát nám pouze potvrdí vaše jméno —
                nepředává nám žádné další osobní údaje.</span>
              </div>
            )}
          </div>

          <div className="flex items-center gap-3 py-1 text-[0.8rem] text-ink-3">
            <span className="h-px flex-1 bg-line" /> nebo <span className="h-px flex-1 bg-line" />
          </div>

          {/* Poskytovatelé s logy */}
          {[
            { p: "Google", label: "Pokračovat přes Google", logo: <GoogleLogo /> },
            { p: "Apple", label: "Pokračovat přes Apple", logo: <AppleLogo /> },
            { p: "Seznam", label: "Pokračovat přes Seznam", logo: <SeznamLogo /> },
          ].map((o) => (
            <button
              key={o.p}
              onClick={() => onProvider(o.p)}
              className="flex w-full items-center justify-center gap-2.5 rounded-2xl border border-line bg-surface px-4 py-3.5 text-[1rem] font-medium text-ink transition-colors hover:border-sage-bd a11y-tap"
            >
              {o.logo} {o.label}
            </button>
          ))}

          <div className="flex items-center gap-3 py-1 text-[0.8rem] text-ink-3">
            <span className="h-px flex-1 bg-line" /> nebo <span className="h-px flex-1 bg-line" />
          </div>
          <button onClick={() => onProvider("email")} className="btn btn-primary w-full text-[1rem]">
            Pokračovat e-mailem
          </button>
          <button
            onClick={() => { setMode("choose"); setSummaryOpen(true); }}
            className="mt-1 flex w-full items-center justify-center gap-1.5 text-[0.8667rem] text-ink-2 hover:text-ink a11y-tap"
          >
            <ArrowLeft size={15} /> Zpět
          </button>
        </div>
      )}

      <p className="mt-6 text-[0.8rem] text-ink-3 text-center">
        GDPR · Vaše údaje jsou v bezpečí · Žádné skryté poplatky
      </p>
    </div>
  );
}
